def transform(grid):
    """Extend upward from each 5 in the bottom row, carrying the last
    encountered nonzero color and preserving original colored cells."""
    out = [row[:] for row in grid]
    h = len(out)
    if h == 0:
        return out
    for c, value in enumerate(out[-1]):
        if value != 5:
            continue
        color = 5
        for r in range(h - 1, -1, -1):
            if out[r][c] != 0:
                color = out[r][c]
            else:
                out[r][c] = color
    return out
